  Future<void> _connect(BuildContext context, AgentConfig config) async {
    // An on-device connect marks the engine configured — its provider row
    // appears in the settings list from now on.
    const onDeviceKinds = {
      webLlmProviderKind,
      gemmaProviderKind,
      transformersJsProviderKind,
    };
    if (onDeviceKinds.contains(config.providerKind)) {
      await OnDeviceConfigScope.maybeOf(
        context,
      )?.markConfigured(config.providerKind);
    }
    final resolvedEnv = env ?? await createPlatformEnv();
    final manager = FlutterSessionManager(
      env: resolvedEnv,
      sessionsRoot: defaultSessionsRoot(resolvedEnv.sessionCwd),
    );
    // Inside the extension panel the relay serves the chat (no local
    // agent, no keys in the UI); null keeps the plain-web local path.
    final relay = await createRelayServiceIfHosted();
    if (relay != null) {
      // Issue #327: the mixed-row guard in reconfigure reads these rows.
      relay.providerRegistry = registry;
      // The relay session id is the SW's; the manager only needs a stable
      // key for the tile/active-session bookkeeping. The local session
      // lifecycle below does not apply — the SW owns the JSONL session.
      // A session_new/session_open from ANY surface arrives as an attach
      // broadcast; re-key the slot so active-dots and labels follow. The
      // hostedLiveId notifier is the single selection source every session
      // UI reads (wide sidebar + narrow drawer) — set it FIRST so the
      // rebuild triggered by the rekey already sees the new truth.
      relay.onLiveSessionIdChanged = (newId) {
        manager.hostedLiveId.value = newId;
        manager.rekeyActiveSession(newId);
      };
      manager.addSession(
        relay.relaySessionId.isEmpty ? 'relay' : relay.relaySessionId,
        relay,
      );
      // The hello/attach handshake completes inside
      // RelayAgentService.create — BEFORE the callback above exists — so
      // the boot-time resync fired into the void; converge once now that
      // the slot exists (no-op when the slot is already keyed right).
      final hostedLiveAtBoot = relay.liveSessionId;
      if (hostedLiveAtBoot != null && hostedLiveAtBoot.isNotEmpty) {
        manager.hostedLiveId.value = hostedLiveAtBoot;
        manager.rekeyActiveSession(hostedLiveAtBoot);
      }
    } else {
      await manager.createOrResumeSession(
        config: config,
        createFactory: () => AgentService.create(
          config: config,
          env: env,
          sessionKeys: sessionKeysStore,
          providerRegistry: registry,
        ),
        openFactory: () => AgentService.create(
          config: config,
          env: env,
          sessionKeys: sessionKeysStore,
          providerRegistry: registry,
        ),
      );
    }
    // Connected — remember where we landed for the next boot (non-secret;
    // the key never reaches the store). Saved before navigation: the push
    // below completes only when the chat screen pops, which may be never.
    await lastConnectionStore?.saveFromConfig(config);
    if (!context.mounted) return;
    final navigator = Navigator.of(context);
    await navigator.pushReplacement(
      MaterialPageRoute(
        builder: (_) => faHomeScreen(
          context: navigator.context,
          manager: manager,
          registry: registry,
          lastConnectionStore: lastConnectionStore,
          restoreAppsMode: true,
          networkMode: networkMode,
          networkSessions: networkSessions,
        ),
      ),
    );
  }

